    pub fn build_folder_path(kit: &Kit, folder_guid: &str) -> String {
        if let Some(folders) = &kit.folders {
            for f in folders {
                if f.guid == folder_guid {
                    if let Some(parent) = &f.parent {
                        let parent_path = build_folder_path(kit, &parent.guid);
